 if(isset($_POST['delete_title'])){DB::execute('DELETE FROM discipline_titles WHERE id=?',[(int)$_POST['title_id']]);redirect('deputy-panel.php?tab=titles');}
 if(isset($_POST['save_record'])){ $sid=(int)$_POST['student_id']; $titleId=(int)($_POST['title_id']??0); $tr=$titleId?DB::fetch('SELECT title FROM discipline_titles WHERE id=?',[$titleId]):null; $title=trim($tr['title']??($_POST['title_text']??'')); $note=trim($_POST['internal_note']??''); $occur=trim($_POST['occurred_at_jalali']??jalali_now()); $notify=isset($_POST['notify_parents'])?1:0; $just=isset($_POST['is_justified'])?1:0; $review=trim($_POST['review_status']??'pending'); $reviewNote=trim($_POST['review_note']??''); if($sid&&$title){DB::execute('INSERT INTO student_discipline_records (student_id,title_id,title_text,internal_note,occurred_at_jalali,notify_parents,is_justified,review_status,review_note,created_by_teacher_id,created_at_jalali) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$sid,$titleId?:null,$title,$note,$occur,$notify,$just,$review,$reviewNote,$teacherId,jalali_now()]); $newRid=DB::lastInsertId(); if($notify) notify_student_discipline_bots($sid,$title,$occur,$newRid);} redirect('deputy-panel.php?student_id='.$sid); }
 if(isset($_POST['delete_record'])){DB::execute('DELETE FROM student_discipline_records WHERE id=?',[(int)$_POST['record_id']]);redirect('deputy-panel.php?student_id='.(int)$_POST['student_id']);}
 if(isset($_POST['update_record'])){ $rid=(int)$_POST['record_id']; $sid=(int)$_POST['student_id']; $title=trim($_POST['title_text']??''); $occur=trim($_POST['occurred_at_jalali']??''); $note=trim($_POST['internal_note']??''); $just=isset($_POST['is_justified'])?1:0; $review=trim($_POST['review_status']??'pending'); DB::execute('UPDATE student_discipline_records SET title_text=?, occurred_at_jalali=?, internal_note=?, is_justified=?, review_status=?, updated_at_jalali=? WHERE id=? AND student_id=?',[$title,$occur,$note,$just,$review,jalali_now(),$rid,$sid]); redirect('deputy-panel.php?student_id='.$sid);}
}
require_once __DIR__ . '/includes/header.php';
$year = resolve_academic_year_request($_GET['academic_year'] ?? get_current_academic_year()); // v4.38.0 unified
$tab=$_GET['tab']??'students'; $q=trim($_GET['q']??''); $grade=trim($_GET['grade']??''); $class=trim($_GET['class']??''); $dFilter=trim($_GET['discipline_filter']??''); $titleFilter=trim($_GET['title_filter']??''); $from=trim($_GET['from_jalali']??''); $to=trim($_GET['to_jalali']??''); $minCount=trim($_GET['min_count']??'');
