$where=["s.status='active'"]; $params=[];
if($q){$where[]='(s.first_name LIKE ? OR s.last_name LIKE ? OR s.national_id LIKE ? OR s.father_name LIKE ?)'; for($i=0;$i<4;$i++)$params[]='%'.$q.'%';}
if($year){
    // Keep year filtering fully consistent with students.php: explicit student year first,
    // then legacy records without academic_year are resolved by reports/schedule/classes of that year.
    $where[]="(s.academic_year=? OR (s.academic_year IS NULL AND EXISTS(SELECT 1 FROM reports ry WHERE ry.student_id=s.id AND ry.academic_year=?)) OR (s.academic_year IS NULL AND EXISTS(SELECT 1 FROM class_schedules cs WHERE cs.academic_year=? AND cs.class_name=s.class_name)) OR (s.academic_year IS NULL AND EXISTS(SELECT 1 FROM classes c WHERE c.academic_year=? AND c.name=s.class_name)))";
    $params[]=$year; $params[]=$year; $params[]=$year; $params[]=$year;
} if($grade){$where[]='s.grade_level=?';$params[]=$grade;} if($class){$where[]='s.class_name=?';$params[]=$class;}
if($dFilter==='has')$where[]='COALESCE(dc.cnt,0)>0'; if($dFilter==='none')$where[]='COALESCE(dc.cnt,0)=0'; if($dFilter==='excellent')$where[]='COALESCE(dc.cnt,0)=0'; if($dFilter==='justified')$where[]='COALESCE(dc.justified_cnt,0)>0'; if($dFilter==='reviewed')$where[]='COALESCE(dc.reviewed_cnt,0)>0'; if($minCount!==''){$where[]='COALESCE(dc.cnt,0)>=?';$params[]=(int)$minCount;}
$sql="SELECT s.*,COALESCE(dc.cnt,0) discipline_count,COALESCE(dc.unreviewed_cnt,0) unreviewed_count,dc.lastd FROM students s LEFT JOIN (SELECT student_id,COUNT(*) cnt,SUM(is_justified=1) justified_cnt,SUM(review_status='reviewed') reviewed_cnt,SUM(CASE WHEN COALESCE(review_status,'pending')='pending' THEN 1 ELSE 0 END) unreviewed_cnt,MAX(occurred_at_jalali) lastd FROM student_discipline_records GROUP BY student_id) dc ON dc.student_id=s.id WHERE ".implode(' AND ',$where);
$students=DB::fetchAll($sql,$params); persian_usort_students($students);
$selectedStudent=(int)($_GET['student_id']??0); $records=$selectedStudent?DB::fetchAll('SELECT * FROM student_discipline_records WHERE student_id=? ORDER BY id DESC',[$selectedStudent]):[]; $st=$selectedStudent?DB::fetch('SELECT * FROM students WHERE id=?',[$selectedStudent]):null;
?>
